class TungoWebhooks:
    """Проверка подписи исходящих вебхуков организации (Svix / Standard Webhooks)."""

    @staticmethod
    def verify_signature(
        raw_body: str | bytes,
        headers: dict[str, str],
        secret: str,
        tolerance_sec: int = 300,
        now_sec: int | None = None,
    ) -> bool:
        low = {k.lower(): v for k, v in headers.items()}
        msg_id = low.get("webhook-id")
        msg_ts = low.get("webhook-timestamp")
        msg_sig = low.get("webhook-signature")
        if not msg_id or not msg_ts or not msg_sig:
            return False
        try:
            ts_int = int(msg_ts)
        except ValueError:
            return False
        current = int(time.time()) if now_sec is None else now_sec
        if tolerance_sec > 0 and abs(current - ts_int) > tolerance_sec:
            return False

        clean_sec = secret[len("whsec_") :] if secret.startswith("whsec_") else secret
        try:
            key = base64.b64decode(clean_sec)
        except Exception:
            return False

        body_str = raw_body.decode("utf-8") if isinstance(raw_body, bytes) else raw_body
        signed = f"{msg_id}.{msg_ts}.{body_str}".encode("utf-8")
        want = hmac.new(key, signed, hashlib.sha256).digest()

        for part in msg_sig.strip().split():
            if "," not in part:
                continue
            ver, b64 = part.split(",", 1)
            if ver != "v1" or not b64:
                continue
            try:
                got = base64.b64decode(b64)
            except Exception:
                continue
            if len(got) == len(want) and hmac.compare_digest(got, want):
                return True
        return False

    @staticmethod
    def verify_and_parse(
        raw_body: str | bytes,
        headers: dict[str, str],
        secret: str,
        tolerance_sec: int = 300,
        now_sec: int | None = None,
    ) -> dict[str, Any]:
        if not TungoWebhooks.verify_signature(raw_body, headers, secret, tolerance_sec=tolerance_sec, now_sec=now_sec):
            raise TungoError("Подпись вебхука не прошла проверку (webhook-signature)")
        body_str = raw_body.decode("utf-8") if isinstance(raw_body, bytes) else raw_body
        return json.loads(body_str)


class TungoHooks:
    """Подпись входящих хуков автоматизации (/hooks/{token}, HMAC-SHA256)."""

    @staticmethod
    def sign_payload(raw_body: str | bytes, secret: str, *, prefix: bool = True) -> str:
        data = raw_body if isinstance(raw_body, bytes) else raw_body.encode("utf-8")
        digest = hmac.new(secret.encode("utf-8"), data, hashlib.sha256).hexdigest()
        return f"sha256={digest}" if prefix else digest


class TungoMoney:
    """Точные операции с деньгами в тиынах (1 ₸ = 100 тиын)."""

    @staticmethod
    def to_tiyn(tenge: float | int) -> int:
        return round(float(tenge) * 100)

    @staticmethod
    def to_tenge(tiyn: int) -> float:
        return tiyn / 100.0

    @staticmethod
    def format_tiyn(tiyn: int) -> str:
        sign = "-" if tiyn < 0 else ""
        abs_val = abs(int(tiyn))
        whole = abs_val // 100
        frac = abs_val % 100
        whole_str = f"{whole:,}".replace(",", " ")
        return f"{sign}{whole_str},{frac:02d} ₸"
